    def ZA_ZL_ACTION(self,action = "RELOAD",lockonflg=1):
        if action != "END":
            if lockonflg == 0:
                if self.ZL_state == 1:
                    self.keys.inputEnd(Button.ZL)
                    self.ZL_state = 0
                return
            if self.ZL_state == 0:
                self.keys.input(Button.ZL)
                self.ZL_state = 1
            else:
                self.keys.inputEnd(Button.ZL)
                #間隔をあけないとロックオンがオンにならない？
                self.wait(0.1)#self.wait(self.SLEEPLIST[2][2])
                self.keys.input(Button.ZL)
                self.ZL_state = 1
        elif action == "END" and self.ZL_state == 1:
            self.keys.inputEnd(Button.ZL)
            self.ZL_state = 0
            
    def ZA_battle_reword_recovery(self, max_press_count=10):
        press_count = 0
        while press_count < max_press_count:
            if not self.image_check("POKEMON_ZA_REWORD"):
                break
            self.checkIfAlive()
            self.pressRep(
                Button.B, repeat=1, duration=0.15,
                wait=0.5, interval=0.1)
            press_count += 1
        return press_count > 0

    def ZA_battle_missing_field_recovery(
            self, counter_key="battle", enabled=True,
            attack_ready=False, before_recovery=None):
        count_name = (
            "_za_battle_missing_field_count_" + str(counter_key))
        # X復帰の報酬表示とXメニューは、FIELD消失回数や
        # 攻撃可否より先に共通入口で処理する。
        if self.ZA_battle_reword_recovery():
            setattr(self, count_name, 0)
            return True
        if self.image_check("POKEMON_ZA_X_MENU_OPEN"):
            setattr(self, count_name, 0)
            self.pressRep(
                Button.B, repeat=1, duration=0.15,
                wait=0.5, interval=0.1)
            return True
        if not enabled or attack_ready:
            setattr(self, count_name, 0)
            return False

        battle_without_field = (
            (not bool(self.ZA_story_Template_Field_HardGaurd()))
            and bool(self.ZA_story_Template_Field_HardGaurd(mode=1))
            and not self.image_check("POKEMON_ZA_BATTLE_ACTIVE_LEVEL"))
        if not battle_without_field:
            setattr(self, count_name, 0)
            return False

        missing_field_count = getattr(self, count_name, 0) + 1
        setattr(self, count_name, missing_field_count)
        if missing_field_count < 10:
            return False

        setattr(self, count_name, 0)
        if callable(before_recovery):
            before_recovery()
        if hasattr(self, "ZA_MOVE_SEE"):
            self.ZA_MOVE_SEE("END")
        self.ZA_ZL_ACTION("END")
        self.pressRep(
            Button.X, repeat=1, duration=0.15,
            wait=0.5, interval=0.1)
        help_press_count = 0
        b_press_count = 0
        while b_press_count < 20:
            # 復帰用Xで報酬が開いた場合は、HELPと同様に
            # 画像を確認しながら、消えるまでBで進める。
            if self.ZA_battle_reword_recovery():
                return True
            # 復帰用XによってXメニューが開いた場合は、背後のFIELD表示で
            # 復帰済みと誤判定する前にBで閉じる。
            if self.image_check("POKEMON_ZA_X_MENU_OPEN"):
                self.checkIfAlive()
                self.pressRep(
                    Button.B, repeat=1, duration=0.15,
                    wait=0.5, interval=0.1)
                return True
            if self.image_check("POKEMON_ZA_HELP_MARKER"):
                if help_press_count >= 10:
                    return True
                # FIELD復帰ループ中のHELPは、消えるまでAで進める。
                # HELP中には選択を変えるBを送らない。
                self.checkIfAlive()
                self.pressRep(
                    Button.A, repeat=1, duration=0.15,
                    wait=0.5, interval=0.1)
                help_press_count += 1
                continue
            if bool(self.ZA_story_Template_Field_HardGaurd()):
                break
            self.checkIfAlive()
            self.pressRep(
                Button.B, repeat=1, duration=0.15,
                wait=0.5, interval=0.1)
            b_press_count += 1
        return True

    def ZA_battle_coCp_noloop(self,Xaction=0,Aaction=0,Yaction=0,Baction=0,lockon_endskip=0,battle_mode=0,selection_up_handled=False):
        select_pictures = (
            "POKEMON_ZA_1_SELECT",
            "POKEMON_ZA_2_SELECT",
            "POKEMON_ZA_3_SELECT",
            "POKEMON_ZA_4_SELECT",
        )

        def advance_selection():
            for picture in select_pictures:
                if self.image_check(picture):
                    # 再戦／交代などの選択肢では攻撃用Bを送らず、
                    # 決定用Aだけを入力する。
                    print(
                        f"[BATTLE_SELECT] {picture} detected -> press A")
                    self.pressRep(
                        Button.A, repeat=1, duration=0.15,
                        wait=0.5, interval=0.1)
                    return True
            return False

        if advance_selection():
            return
        if not selection_up_handled:
            if battle_mode==0 and self.image_check("POKEMON_ZA_SELECT"):
                self.etc_sendCommand("Lbutton_up")
            elif battle_mode==1 and self.image_check("POKEMON_ZA_FIELD_W"):
                self.etc_sendCommand("Lbutton_up")
        recovery_enabled = not (
            self.image_check("POKEMON_ZA_2_SELECT")
            or self.image_check("POKEMON_ZA_3_SELECT")
            or self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT"))
        if self.ZA_battle_missing_field_recovery(
                "cocp", enabled=recovery_enabled):
            return

        self.ZA_ZL_ACTION("")
        # ロックオンがゲーム側へ反映されてから攻撃を開始する。
        self.wait(0.1)
        for i in range(3):
            # 攻撃中に選択肢へ切り替わった場合も、以降のX/A/Y/Bを
            # 中断してA決定へ切り替える。
            if advance_selection():
                return
            if Xaction==1:
                self.pressRep(Button.X, repeat=1, duration=0.04, wait=0.0, interval=0.1)
            if advance_selection():
                return
            if Aaction==1:
                self.pressRep(Button.A, repeat=1, duration=0.04, wait=0.0, interval=0.1)
            if advance_selection():
                return
            if Yaction==1:
                self.pressRep(Button.Y, repeat=1, duration=0.04, wait=0.0, interval=0.1)
            if advance_selection():
                return
            if Baction==1:
                self.pressRep(Button.B, repeat=1, duration=0.04, wait=0.0, interval=0.1)
        if lockon_endskip==0:
            self.ZA_ZL_ACTION("END")
            
    def ZA_battle_Cp_loop(self,Xaction=0,Aaction=0,Yaction=0,Baction=0,lockon_endskip=0,get_chanceicon4=0,mode=0,battle_mode=0,Cp_low_check=0,usenum=1,R_Push_enable=1,view_lockon_mode=0,lockon_attack_wait=0.0,lockon_attack_checks=1,y_first_attack=0,a_repeat=1):
        noCp_count=0
        target_marker=1
        nofiled=1
        a_repeat_count = max(1, int(a_repeat))
        y_first_pending = (y_first_attack == 1 and Yaction == 1)

        def cplus_ready():
            # 通常閾値で取りこぼした場合はLOWへフォールバックする。
            return (
                self.image_check("POKEMON_ZA_C+")
                or self.image_check("POKEMON_ZA_C+_LOW"))

        def execute_attack_buttons():
            nonlocal y_first_pending
            # 既定のX→A→Y→Bは保持する。指定時はYを1回だけ
            # 先頭で送り、以後のC+成立ではX→Aだけを繰り返す。
            if y_first_attack == 1:
                attack_order = []
                if y_first_pending:
                    attack_order.append((Yaction, Button.Y, 1))
                    y_first_pending = False
                attack_order.extend((
                    (Xaction, Button.X, 1),
                    (Aaction, Button.A, a_repeat_count),
                    (Baction, Button.B, 1),
                ))
            else:
                attack_order = (
                    (Xaction, Button.X, 1),
                    (Aaction, Button.A, a_repeat_count),
                    (Yaction, Button.Y, 1),
                    (Baction, Button.B, 1),
                )
            for enabled, button, repeat_count in attack_order:
                if enabled == 1:
                    self.pressRep(
                        button, repeat=repeat_count, duration=0.04,
                        wait=0.0, interval=0.1)

        while True:
            print(f'noCp_count = {noCp_count} mode = {mode} battle_mode = {battle_mode}')
            self.checkIfAlive()

            recovery_enabled = not (
                self.image_check("POKEMON_ZA_2_SELECT")
                or self.image_check("POKEMON_ZA_3_SELECT")
                or self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT"))
            cp_attack_ready = cplus_ready()
            if self.ZA_battle_missing_field_recovery(
                    "cp_loop", enabled=recovery_enabled,
                    attack_ready=cp_attack_ready):
                continue
            
            if nofiled==1 and (self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK")): #FIELDから変更
                if (usenum==1 and self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK") and (self.image_check("POKEMON_ZA_FIELD1") or self.image_check("POKEMON_ZA_FIELD_BACK1"))): #FIELDから変更
                    self.wait(0.5)
                    self.etc_sendCommand("Lbutton_up")
                    nofiled=0
                elif (usenum==2 and self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK") and (self.image_check("POKEMON_ZA_FIELD2") or self.image_check("POKEMON_ZA_FIELD_BACK2"))): #FIELDから変更
                    self.wait(0.5)
                    self.etc_sendCommand("Lbutton_up")
                    nofiled=0
                elif (usenum==3 and self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK") and (self.image_check("POKEMON_ZA_FIELD3") or self.image_check("POKEMON_ZA_FIELD_BACK3"))): #FIELDから変更
                    self.wait(0.5)
                    self.etc_sendCommand("Lbutton_up")
                    nofiled=0
                elif (usenum==4 and self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK") and (self.image_check("POKEMON_ZA_FIELD4") or self.image_check("POKEMON_ZA_FIELD_BACK4"))): #FIELDから変更
                    self.wait(0.5)
                    self.etc_sendCommand("Lbutton_up")
                    nofiled=0
                elif (usenum==5 and self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK") and (self.image_check("POKEMON_ZA_FIELD5") or self.image_check("POKEMON_ZA_FIELD_BACK5"))): #FIELDから変更
                    self.wait(0.5)
                    self.etc_sendCommand("Lbutton_up")
                    nofiled=0
                elif (usenum==6 and self.image_check("POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK") and (self.image_check("POKEMON_ZA_FIELD6") or self.image_check("POKEMON_ZA_FIELD_BACK6"))): #FIELDから変更
                    self.wait(0.5)
                    self.etc_sendCommand("Lbutton_up")
                    nofiled=0
                else:
                    self.etc_sendCommand("Lbutton_left")
                    self.wait(0.5)
                    continue
            
            elif battle_mode==0 and self.image_check("POKEMON_ZA_SELECT"):
                self.etc_sendCommand("Lbutton_up")
            elif battle_mode==1 and self.image_check("POKEMON_ZA_FIELD_W"):
                self.etc_sendCommand("Lbutton_up")
                
            if ((R_Push_enable == 1) and self.image_check("POKEMON_ZA_R_push")):
                self.press(Button.RCLICK,0.05,0.1) 

            # 指定時はnoCp_countを待たず、既存の視点回転を開始してから
            # ZLを再入力する。既定OFFなので既存呼出しの動作は変えない。
            if view_lockon_mode == 1:
                self.ZA_MOVE_SEE(action="", in_see_r=0.6)
            self.ZA_ZL_ACTION("")
            lockon_cplus_ready = False
            attack_checks = max(1, int(lockon_attack_checks))
            if attack_checks > 1:
                # ZLを保持したままC+を複数回確認する。最初は待たずに
                # 判定し、一致した時点で残りの待機を行わず攻撃へ進む。
                check_interval = (
                    max(0.0, float(lockon_attack_wait))
                    / float(attack_checks - 1))
                for check_index in range(attack_checks):
                    if cplus_ready():
                        lockon_cplus_ready = True
                        break
                    if check_index + 1 < attack_checks:
                        self.wait(check_interval)
            elif lockon_attack_wait > 0:
                # 既定1回確認の呼出しは従来どおり指定時間後に判定する。
                self.wait(lockon_attack_wait)
            
            for i in range(5):
                current_cplus_ready = (
                    lockon_cplus_ready or cplus_ready())
                #バトル中チェック チェックできない場合は、一旦抜ける
                if mode==0 and (self.image_check("POKEMON_ZA_BATTLE_BALL_CHECK") or self.image_check("POKEMON_ZA_ESCAPE") or current_cplus_ready):
                    
                    if get_chanceicon4==1 and self.image_check("POKEMON_ZA_GETCHANCE_ICON4"):
                        self.ZA_get_pokemon()
                    if current_cplus_ready:
                        lockon_cplus_ready = False
                        noCp_count=0
                        execute_attack_buttons()
                        self.ZA_MOVE_SEE(action = "END",in_see_r=0.6)
