    ######################################################
    # story_Template
    ######################################################
    def _ZA_story_furadari_allow_comment_retry(
            self, recovery_target, current_state):
        """明示的に前へ戻す区間内だけComment_Outの再試行を許可する。"""
        skipped_states = getattr(
            self, "_za_story_furadari_comment_skipped", None)
        if not skipped_states:
            return
        try:
            recovery_number = int(str(recovery_target).rsplit("_", 1)[1])
            current_number = int(str(current_state).rsplit("_", 1)[1])
        except (IndexError, TypeError, ValueError):
            return
        retry_states = set()
        for state in skipped_states:
            if not state.startswith("7_STORY_GURI_"):
                continue
            try:
                state_number = int(state.rsplit("_", 1)[1])
            except (IndexError, TypeError, ValueError):
                continue
            if recovery_number < state_number <= current_number:
                retry_states.add(state)
        if retry_states:
            skipped_states.difference_update(retry_states)
            timers = getattr(
                self, "_za_story_event_entry_recovery_started", None)
            if timers is not None:
                for state in retry_states:
                    timers.pop(state, None)
            print(
                "[FURADARI_COMMENT_TIMEOUT] explicit recovery {} -> {}; "
                "allow retry={}".format(
                    current_state, recovery_target,
                    ",".join(sorted(retry_states))))

    def ZA_story_furadari_section_recovery_step(
            self, current_state, normal_return):
        """暗転した区間を、2つ前のFURADARI_MAP gotoから再開する。"""
        def recovery_log(message, level="info"):
            print(message)
            logger = getattr(self, "_logger", None)
            log_method = getattr(logger, level, None)
            if callable(log_method):
                log_method(message)

        # 「目の前がまっくらになった！」を一度でも検知したら、判定待ち中も
        # 専用復帰が完了するまで通常の周辺暗転復帰へ渡さない。初回Bの後に
        # ロードで再表示される黒Commentも、この専用フローだけが閉じる。
        eyes_dark_lock_state = getattr(
            self, "_za_furadari_eyes_dark_recovery_lock_state", None)
        if eyes_dark_lock_state is not None:
            dedicated_recovery = getattr(
                self, "_za_furadari_black_recovery", None)
            if (isinstance(dedicated_recovery, dict)
                    and dedicated_recovery.get("dark_comment")):
                return dedicated_recovery.get(
                    "holding_state", eyes_dark_lock_state)
            if eyes_dark_lock_state == current_state:
                return current_state

        recovery_targets = getattr(
            self, "ZA_STORY_FURADARI_SECTION_RECOVERY_TARGETS", {})
        recovery_target = recovery_targets.get(current_state)
        pending_state = getattr(
            self, "_za_furadari_section_recovery_state", None)

        def clear_dark_candidate():
            if (getattr(
                    self, "_za_furadari_section_dark_candidate_state", None)
                    == current_state):
                self._za_furadari_section_dark_candidate_state = None
                self._za_furadari_section_dark_candidate_started = None

        if recovery_target is None:
            clear_dark_candidate()
            if pending_state is not None:
                self._za_furadari_section_recovery_state = None
                self._za_furadari_section_recovery_b_count = 0
                self._za_furadari_section_recovery_limit_logged = False
                self._za_furadari_section_recovery_no_frame_logged = False
            return normal_return

        # 正常に次Stepへ進めた場合は、暗転判定を追加せず通常遷移を優先する。
        if normal_return != current_state:
            clear_dark_candidate()
            if pending_state == current_state:
                self._za_furadari_section_recovery_state = None
                self._za_furadari_section_recovery_b_count = 0
                self._za_furadari_section_recovery_limit_logged = False
                self._za_furadari_section_recovery_no_frame_logged = False
            return normal_return

        if pending_state != current_state:
            if not self._ZA_furadari_screen_is_dark(
                    log_detection=False):
                clear_dark_candidate()
                return normal_return
            now = time.monotonic()
            candidate_state = getattr(
                self, "_za_furadari_section_dark_candidate_state", None)
            candidate_started = getattr(
                self, "_za_furadari_section_dark_candidate_started", None)
            if candidate_state != current_state or candidate_started is None:
                self._za_furadari_section_dark_candidate_state = current_state
                self._za_furadari_section_dark_candidate_started = now
                hold_seconds = float(getattr(
                    self, "ZA_STORY_FURADARI_DARK_RECOVERY_SECONDS", 5.0))
                recovery_log(
                    "[FURADARI_SECTION_RECOVERY] {} dark candidate; "
                    "wait {:.1f}s before B recovery".format(
                        current_state, hold_seconds))
                if hold_seconds > 0.0:
                    return normal_return
                candidate_started = now
            hold_seconds = float(getattr(
                self, "ZA_STORY_FURADARI_DARK_RECOVERY_SECONDS", 5.0))
            if now - candidate_started < hold_seconds:
                return normal_return
            clear_dark_candidate()
            self._za_furadari_section_recovery_state = current_state
            self._za_furadari_section_recovery_b_count = 0
            self._za_furadari_section_recovery_limit_logged = False
            self._za_furadari_section_recovery_no_frame_logged = False
            reason = getattr(
                self, "_za_furadari_dark_detection_reason", "dark")
            recovery_log(
                "[FURADARI_SECTION_RECOVERY] {} reason={}; press B up to "
                "30 times and check FIELD after every input, then return "
                "to {}".format(current_state, reason, recovery_target),
                level="warning")

        b_count = int(getattr(
            self, "_za_furadari_section_recovery_b_count", 0))

        def field_is_visible():
            # 入力停止中にHardGuard内の各画像検知がそれぞれ0.75秒待つと、
            # B30回より先に60秒のCommands暗転安全停止へ到達する。
            # 新規フレームがない周回は即座に未検知とし、復帰後の次周で
            # 同じHardGuardを1回だけ評価する。
            camera = getattr(self, "camera", None)
            has_fresh_frame = getattr(camera, "hasFreshFrame", None)
            if callable(has_fresh_frame) and not has_fresh_frame():
                if not getattr(
                        self,
                        "_za_furadari_section_recovery_no_frame_logged",
                        False):
                    recovery_log(
                        "[FURADARI_SECTION_RECOVERY] FIELD check waiting: "
                        "live camera frame unavailable",
                        level="warning")
                    self._za_furadari_section_recovery_no_frame_logged = True
                return False
            self._za_furadari_section_recovery_no_frame_logged = False
            return bool(self.image_check(
                "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK_0"))

        # 暗転画面の背景がFIELDへ誤一致しても、最低1回はBを送ってから
        # 復帰完了とする。30回到達後は追加のBを送らずFIELDだけを待つ。
        field_visible = bool(b_count > 0 and field_is_visible())
        while not field_visible and b_count < 30:
            self.checkIfAlive()
            self.pressRep(
                Button.B, repeat=1, duration=0.15,
                wait=0.1, interval=0.1)
            b_count += 1
            self._za_furadari_section_recovery_b_count = b_count
            field_visible = field_is_visible()
            if b_count in {1, 5, 10, 20, 30}:
                recovery_log(
                    "[FURADARI_SECTION_RECOVERY] {} B count={} "
                    "FIELD={}".format(
                        current_state, b_count, field_visible))

        if field_visible:
            self._za_furadari_section_recovery_state = None
            self._za_furadari_section_recovery_b_count = 0
            self._za_furadari_section_recovery_limit_logged = False
            self._za_furadari_section_recovery_no_frame_logged = False
            # 戻り先のZA_Common_gotoを必ず先頭から開始する。
            self.Common_current_state = "COMMON_START"
            self.map_cursor_reset = 0
            allow_comment_retry = getattr(
                self, "_ZA_story_furadari_allow_comment_retry", None)
            if callable(allow_comment_retry):
                allow_comment_retry(recovery_target, current_state)
            recovery_log(
                "[FURADARI_SECTION_RECOVERY] FIELD restored after "
                "B count={} : {} -> {}".format(
                    b_count, current_state, recovery_target))
            return recovery_target

        if not getattr(
                self, "_za_furadari_section_recovery_limit_logged", False):
            recovery_log(
                "[FURADARI_SECTION_RECOVERY] FIELD not detected after "
                "B x30 at {}; wait without additional B input".format(
                    current_state),
                level="warning")
            self._za_furadari_section_recovery_limit_logged = True
        self.wait(0.1)
        return current_state

    def _ZA_furadari_eyes_dark_comment_visible(self):
        """Match the raw 1280x720 Switch No2 capture target."""
        matched = bool(self.image_check(
            "POKEMON_ZA_FURADARI_EYES_DARK_COMMENT"))
        detail = getattr(self, "last_image_detection", {}) or {}
        score = float(detail.get("score", 0.0) or 0.0)
        threshold = float(detail.get("threshold", 0.85) or 0.85)
        print(
            "[FURADARI_EYES_DARK_DETECTION] source=raw_capture "
            "score={:.6f} threshold={:.6f} matched={}".format(
                score, threshold, matched))
        return matched

    def ZA_story_furadari_black_comment_recovery_step(
            self, current_state, state_functions):
        """Recover a stuck black comment from an earlier FURADARI goto."""
        def recovery_log(message, level="info"):
            print(message)
            logger = getattr(self, "_logger", None)
            log_method = getattr(logger, level, None)
            if callable(log_method):
                log_method(message)

        def clear_candidate():
            self._za_furadari_black_candidate_state = None
            self._za_furadari_black_candidate_started = None
            self._za_furadari_black_candidate_eyes_dark = False
            # 専用復帰がまだ生成されていない候補だけを解除する。生成後は
            # 最終FURADARI_MAP復帰までロックを保持する。
            if getattr(self, "_za_furadari_black_recovery", None) is None:
                self._za_furadari_eyes_dark_recovery_lock_state = None

        def eyes_dark_is_visible():
            eyes_dark_check = getattr(
                self, "_ZA_furadari_eyes_dark_comment_visible", None)
            if callable(eyes_dark_check):
                return bool(eyes_dark_check())
            return bool(self.image_check(
                "POKEMON_ZA_FURADARI_EYES_DARK_COMMENT"))

        def reserve_eyes_dark_recovery():
            """Keep all FURADARI recovery input in the eyes-dark route."""
            self._za_furadari_eyes_dark_recovery_lock_state = current_state
            # 既に作られた周辺暗転候補も含めて破棄する。これを残すと、
            # 初回Bのロード後に周辺処理が2回目の黒Commentへ入力し得る。
            self._za_furadari_section_dark_candidate_state = None
            self._za_furadari_section_dark_candidate_started = None
            self._za_furadari_section_recovery_state = None
            self._za_furadari_section_recovery_b_count = 0
            self._za_furadari_section_recovery_limit_logged = False
            self._za_furadari_section_recovery_no_frame_logged = False

        def field_is_visible():
            return bool(self.image_check(
                "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK_0"))

        recovery = getattr(
            self, "_za_furadari_black_recovery", None)
        recovery_states = getattr(
            self, "ZA_STORY_FURADARI_BLACK_RECOVERY_STATES", ())

        # 通常の黒Comment処理を先に30秒間試す。途中でCommentが消えた、
        # またはStepが進んだ場合は復帰処理を開始しない。
        if recovery is None:
            if current_state not in recovery_states:
                clear_candidate()
                return None
            if not self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT"):
                clear_candidate()
                return None

            now = time.monotonic()
            candidate_state = getattr(
                self, "_za_furadari_black_candidate_state", None)
            candidate_started = getattr(
                self, "_za_furadari_black_candidate_started", None)
            if candidate_state != current_state or candidate_started is None:
                self._za_furadari_black_candidate_state = current_state
                self._za_furadari_black_candidate_started = now
                candidate_started = now
                # 「目の前がまっくらになった！」は30秒待機中に消えるため、
                # 汎用黒Commentを最初に見つけた瞬間の判定を記録しておく。
                candidate_eyes_dark = eyes_dark_is_visible()
                self._za_furadari_black_candidate_eyes_dark = (
                    candidate_eyes_dark)
                recovery_log(
                    "[FURADARI_BLACK_RECOVERY] {} black comment candidate; "
                    "wait {:.1f}s before recovery".format(
                        current_state,
                        float(getattr(
                            self,
                            "ZA_STORY_FURADARI_BLACK_RECOVERY_SECONDS",
                            30.0))))
                recovery_log(
                    "[FURADARI_EYES_DARK_LATCH] state={} "
                    "candidate_start matched={}".format(
                        current_state, candidate_eyes_dark))
            else:
                candidate_eyes_dark = bool(getattr(
                    self, "_za_furadari_black_candidate_eyes_dark", False))
                # 黒Commentが先に見え、少し後から専用の文言が描画される
                # ケースもあるため、未ラッチ時だけ追加で確認する。
                if not candidate_eyes_dark and eyes_dark_is_visible():
                    candidate_eyes_dark = True
                    self._za_furadari_black_candidate_eyes_dark = True
                    recovery_log(
                        "[FURADARI_EYES_DARK_LATCH] state={} "
                        "matched_after_candidate_start=True".format(
                            current_state))

            if candidate_eyes_dark:
                # この時点から通常Step／周辺の黒Comment復帰を止める。黒Comment
                # が30秒未満で消えた場合は次周のclear_candidateで解除される。
                reserve_eyes_dark_recovery()

            recovery_seconds = float(getattr(
                self, "ZA_STORY_FURADARI_BLACK_RECOVERY_SECONDS", 30.0))
            if now - candidate_started < recovery_seconds:
                return current_state if candidate_eyes_dark else None

            # 30秒到達時には専用Commentがロード後に消えていることがある。
            # 最初に記録した一致を優先し、最初に取りこぼした場合だけ
            # 到達時の画面も再照合する。
            latched_dark_comment = bool(getattr(
                self, "_za_furadari_black_candidate_eyes_dark", False))
            timeout_dark_comment = (
                False if latched_dark_comment else eyes_dark_is_visible())
            dark_comment = bool(
                latched_dark_comment or timeout_dark_comment)
            recovery_log(
                "[FURADARI_EYES_DARK_LATCH] state={} "
                "candidate_start={} timeout={} selected={}".format(
                    current_state, latched_dark_comment,
                    timeout_dark_comment, dark_comment))
            fallback = getattr(
                self, "ZA_STORY_FURADARI_BLACK_RECOVERY_FALLBACK",
                "7_STORY_GURI_87")
            section_targets = getattr(
                self, "ZA_STORY_FURADARI_SECTION_RECOVERY_TARGETS", {})
            recovery_target = section_targets.get(current_state, fallback)
            field_return_states = getattr(
                self, "ZA_STORY_FURADARI_EYES_DARK_FIELD_RETURN_STATES", ())
            field_return_without_goto = bool(
                dark_comment and current_state in field_return_states)
            if field_return_without_goto:
                recovery_target = getattr(
                    self, "ZA_STORY_FURADARI_EYES_DARK_FIELD_RETURN_TARGET",
                    "7_STORY_GURI_114")
            recovery = {
                "recovery_target": recovery_target,
                "holding_state": current_state,
                "dark_comment": dark_comment,
                "field_return_without_goto": field_return_without_goto,
                "close_button": Button.B,
                "close_count": 0,
                "limit_logged": False,
                "phase": (
                    "INITIAL_EYES_DARK_B"
                    if dark_comment else "CLOSE_COMMENT"),
                "map_state": "COMMON_MAP_OPEN",
            }
            self._za_furadari_black_recovery = recovery
            clear_candidate()
            if dark_comment:
                reserve_eyes_dark_recovery()
            # 競合する暗転復帰候補を破棄し、この専用経路だけを進める。
            self._za_furadari_section_dark_candidate_state = None
            self._za_furadari_section_dark_candidate_started = None
            self._za_furadari_section_recovery_state = None
            recovery_log(
                "[FURADARI_BLACK_RECOVERY] {} black comment persisted "
                "{:.1f}s; eyes_dark={} close_button={}".format(
                    current_state, recovery_seconds, dark_comment,
                    "B"),
                level="warning")

        holding_state = recovery.get("holding_state", current_state)
        phase = recovery.get("phase", "CLOSE_COMMENT")

        # 専用の「目の前がまっくらになった！」は、最初にBを一度だけ
        # 押して閉じる。その直後にはロードが入るため、この時点では
        # FIELDやマップへ進めない。
        if phase == "INITIAL_EYES_DARK_B":
            self.checkIfAlive()
            self.pressRep(
                recovery["close_button"], repeat=1, duration=0.15,
                wait=0.1, interval=0.1)
            recovery["phase"] = "WAIT_INITIAL_BLACK_CLEAR"
            recovery_log(
                "[FURADARI_BLACK_RECOVERY] initial eyes-dark B sent; "
                "wait for black comment to clear")
            return holding_state

        # 1回目の黒Commentが消えたことを確認してから、ロード後に出る
        # 2回目の黒Commentを待つ。ここではB連打をしない。
        if phase == "WAIT_INITIAL_BLACK_CLEAR":
            if self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT"):
                self.wait(0.1)
                return holding_state
            recovery["phase"] = "WAIT_POST_LOAD_BLACK_COMMENT"
            recovery_log(
                "[FURADARI_BLACK_RECOVERY] initial black comment cleared; "
                "wait for post-load black comment")
            return holding_state

        # ロード後の黒Commentを検知してから、FIELDまで最大70回のB連打を
        # 開始する。途中で黒Commentが一度消えても、FIELD確認までは継続する。
        if phase == "WAIT_POST_LOAD_BLACK_COMMENT":
            if not self.image_check("POKEMON_ZA_TEXT_BLACK_COMMENT"):
                self.wait(0.1)
                return holding_state
            recovery["phase"] = "CLOSE_COMMENT"
            recovery["close_count"] = 0
            phase = "CLOSE_COMMENT"
            recovery_log(
                "[FURADARI_BLACK_RECOVERY] post-load black comment "
                "detected; start B up to 70 every 1.0s until FIELD")

        if phase == "CLOSE_COMMENT":
            close_count = int(recovery.get("close_count", 0))
            dark_comment = bool(recovery["dark_comment"])
            if dark_comment:
                input_limit = int(getattr(
                    self,
                    "ZA_STORY_FURADARI_EYES_DARK_RECOVERY_MAX_INPUTS",
                    70))
                b_interval_seconds = float(getattr(
                    self,
                    "ZA_STORY_FURADARI_EYES_DARK_B_INTERVAL_SECONDS",
                    1.0))
            else:
                input_limit = int(getattr(
                    self, "ZA_STORY_FURADARI_BLACK_RECOVERY_MAX_INPUTS", 30))
                b_interval_seconds = 0.25

            # 黒Comment背景のFIELD誤一致を避けるため、最低1回Bを送った後に
            # FIELDを確認する。以後はBの直後ごとに確認し、最大回数で止める。
            field_visible = bool(close_count > 0 and field_is_visible())
            while not field_visible and close_count < input_limit:

                self.checkIfAlive()
                press_duration = 0.15
                press_wait = (
                    max(0.0, b_interval_seconds - press_duration)
                    if dark_comment else 0.1)
                self.pressRep(
                    recovery["close_button"], repeat=1,
                    duration=press_duration,
                    wait=press_wait,
                    interval=(b_interval_seconds if dark_comment else 0.1))
                close_count += 1
                recovery["close_count"] = close_count
                field_visible = field_is_visible()
            if not field_visible:
                if not recovery.get("limit_logged", False):
                    recovery_log(
                        "[FURADARI_BLACK_RECOVERY] {} not FIELD after {} "
                        "x{}; wait without additional input".format(
                            holding_state,
                            "B",
                            input_limit),
                        level="warning")
                    recovery["limit_logged"] = True
                self.wait(0.1)
                return holding_state

            recovery["limit_logged"] = False
            self.map_cursor_reset = 0
            if dark_comment:
                if recovery.get("field_return_without_goto", False):
                    recovery["phase"] = "RETURN_GURI_114_FROM_FIELD"
                    recovery_log(
                        "[FURADARI_BLACK_RECOVERY] FIELD restored after B "
                        "count={}; skip goto, move left90 4.0s and return "
                        "to 7_STORY_GURI_114".format(close_count))
                else:
                    recovery["phase"] = "ALTERNATE_GOTO"
                    recovery["map_state"] = "COMMON_MAP_OPEN"
                    recovery_log(
                        "[FURADARI_BLACK_RECOVERY] FIELD restored after B "
                        "count={}; start alternate goto filter_down=1 "
                        "spot_right=1 spot_down=1".format(close_count))
            else:
                recovery["phase"] = "RETRY_FURADARI"
                self.Common_current_state = "COMMON_START"
                recovery_log(
                    "[FURADARI_BLACK_RECOVERY] FIELD restored after B "
                    "count={}; retry POKEMON_ZA_FURADARI_MAP".format(
                        close_count))
            return holding_state

        if phase == "RETURN_GURI_114_FROM_FIELD":
            self.press(
                Direction(Stick.LEFT, 90), duration=4.0, wait=1.0)
            resume_state = recovery.get(
                "recovery_target", "7_STORY_GURI_114")
            if resume_state not in state_functions:
                resume_state = "7_STORY_GURI_114"
            self._za_furadari_black_recovery = None
            self._za_furadari_eyes_dark_recovery_lock_state = None
            self.Common_current_state = "COMMON_START"
            self.map_cursor_reset = 0
            allow_comment_retry = getattr(
                self, "_ZA_story_furadari_allow_comment_retry", None)
            if callable(allow_comment_retry):
                allow_comment_retry(resume_state, holding_state)
            recovery_log(
                "[FURADARI_BLACK_RECOVERY] skip goto complete; moved "
                "left90 4.0s and return to {}".format(resume_state))
            return resume_state

        if phase == "ALTERNATE_GOTO":
            common_state = recovery.get("map_state", "COMMON_MAP_OPEN")
            if common_state == "COMMON_MAP_OPEN":
                # 退避先への移動は通常マップ。FURADARI_MAP用の
                # othermap判定は、最後に元の場所へ戻すgotoだけで使う。
                next_state = self.ZA_Common_map_open()
            elif common_state == "COMMON_GOTO_SELECT1":
                # MINUSで移動先種別を開き、「施設」（下1）を選ぶ。
                next_state = self.ZA_Common_goto_select1(1)
            elif common_state == "COMMON_GOTO_SELECT2":
                # 移動スポットを現在位置から右1・下1で選ぶ。
                next_state = self.ZA_Common_goto_select2(
                    1, 1, 0, battle_recovery_mode=0,
                    force_filter_navigation=True)
            elif common_state in {
                    "COMMON_CHANGE_TIME", "COMMON_CHECK_TIME"}:
                next_state = common_state
            else:
                common_function = getattr(
                    self, "STATE_COMMON_FUNCTION", {}).get(common_state)
                if not callable(common_function):
                    recovery_log(
                        "[FURADARI_BLACK_RECOVERY] unknown alternate map "
                        "state={}; restart map selection".format(
                            common_state),
                        level="warning")
                    self.map_cursor_reset = 0
                    next_state = "COMMON_MAP_OPEN"
                else:
                    next_state = common_function()
            recovery["map_state"] = next_state
            if next_state in {"COMMON_CHANGE_TIME", "COMMON_CHECK_TIME"}:
                recovery["phase"] = "WAIT_FIRST_FIELD"
                recovery["map_state"] = "COMMON_START"
                recovery_log(
                    "[FURADARI_BLACK_RECOVERY] alternate goto complete; "
                    "wait for FIELD")
            return holding_state

        if phase == "WAIT_FIRST_FIELD":
            if not field_is_visible():
                self.wait(0.1)
                return holding_state
            self.press(
                Direction(Stick.LEFT, 90), duration=3.0, wait=1.0)
            self.pressRep(
                Button.A, repeat=1, duration=0.15,
                wait=0.5, interval=0.1)
            recovery["phase"] = "WAIT_SECOND_FIELD"
            recovery_log(
                "[FURADARI_BLACK_RECOVERY] FIELD -> move left90 3.0s "
                "and A; wait for next FIELD")
            return holding_state

        if phase == "WAIT_SECOND_FIELD":
            if not field_is_visible():
                self.wait(0.1)
                return holding_state
            self.press(
                Direction(Stick.LEFT, 90), duration=5.0, wait=1.0)
            recovery["phase"] = "RETRY_FURADARI"
            self.Common_current_state = "COMMON_START"
            recovery_log(
                "[FURADARI_BLACK_RECOVERY] next FIELD -> move left90 "
                "5.0s; retry POKEMON_ZA_FURADARI_MAP")
            return holding_state

        goto_result = self.ZA_Common_goto(
            0, 0, 0, othermap="POKEMON_ZA_FURADARI_MAP",
            battle_recovery_mode=1)
        if goto_result != "START":
            return holding_state

        fallback = getattr(
            self, "ZA_STORY_FURADARI_BLACK_RECOVERY_FALLBACK",
            "7_STORY_GURI_87")
        resume_state = recovery.get("recovery_target", fallback)
        if resume_state not in state_functions:
            resume_state = fallback
        self._za_furadari_black_recovery = None
        self._za_furadari_eyes_dark_recovery_lock_state = None
        self.Common_current_state = "COMMON_START"
        self.map_cursor_reset = 0
        allow_comment_retry = getattr(
            self, "_ZA_story_furadari_allow_comment_retry", None)
        if callable(allow_comment_retry):
            allow_comment_retry(resume_state, holding_state)
        recovery_log(
            "[FURADARI_BLACK_RECOVERY] FURADARI_MAP restored; "
            "return to earlier goto {} (fallback={})".format(
                resume_state, fallback))
        return resume_state

    def ZA_story_event_entry_recovery_step(
            self, current_state, state_functions):
        """町イベントへ入れなかったStepを、指定時間後に復帰先へ移す。"""
        # FURADARI区間の黒Commentが30秒継続した場合は、通常Stepを
        # 再実行せず専用の復帰Stateを進める。
        black_recovery = getattr(
            self, "ZA_story_furadari_black_comment_recovery_step", None)
        if callable(black_recovery):
            recovery_return = black_recovery(
                current_state, state_functions)
            if recovery_return is not None:
                return recovery_return

        # 専用画像を見た候補は30秒確認中からロックする。万一、候補関数が
        # Noneを返す経路でもStep本体や周辺の黒Comment処理を実行しない。
        eyes_dark_lock_state = getattr(
            self, "_za_furadari_eyes_dark_recovery_lock_state", None)
        if eyes_dark_lock_state is not None:
            dedicated_recovery = getattr(
                self, "_za_furadari_black_recovery", None)
            if isinstance(dedicated_recovery, dict):
                return dedicated_recovery.get(
                    "holding_state", eyes_dark_lock_state)
            return eyes_dark_lock_state

        # B30復帰中はFIELD移動Step本体を再実行しない。FIELDへ戻った周回で
        # そのまま移動を始めず、対応するFURADARI_MAP gotoへ戻す。
        if (getattr(
                self, "_za_furadari_section_recovery_state", None)
                == current_state):
            return self.ZA_story_furadari_section_recovery_step(
                current_state, current_state)

        # Comment_Outなしで一度タイムアウト済みなら、通常の再訪では
        # Comment_Outを再実行せず、前回と同じ次Stepへ直ちに進める。
        furadari_comment_targets = getattr(
            self, "ZA_STORY_FURADARI_COMMENT_SKIP_TARGETS", {})
        skipped_furadari_comments = getattr(
            self, "_za_story_furadari_comment_skipped", set())
        if current_state in skipped_furadari_comments:
            next_state = furadari_comment_targets.get(current_state)
            if next_state is not None:
                print(
                    "[FURADARI_COMMENT_TIMEOUT] already skipped: "
                    "{} -> {}".format(current_state, next_state))
                return next_state

        # Story側のチケット集めStepへ入った時だけ、前のランクで立った
        # 満杯フラグを破棄する。同じStep内の周回では再初期化しない。
        # ZA_INFI単体実行はこのStory用ラッパーを通らないため対象外。
        is_lank_battle_zone = str(current_state).endswith(
            "_LANK_BATTLE_ZONE")
        if is_lank_battle_zone:
            active_lank_battle_zone = getattr(
                self, "_za_story_active_lank_battle_zone", None)
            if active_lank_battle_zone != current_state:
                previous_chicketmaxflag = self.chicketmaxflag
                self.chicketmaxflag = 0
                self._za_story_active_lank_battle_zone = current_state
                print(
                    f"[LANK_BATTLE_ZONE] {current_state} entry: "
                    f"chicketmaxflag {previous_chicketmaxflag} -> 0")
        else:
            self._za_story_active_lank_battle_zone = None

        state_function = state_functions[current_state]
        function_names = getattr(
            getattr(state_function, "__func__", state_function),
            "__code__", None)
        function_names = getattr(function_names, "co_names", ())
        is_battle_function = any(name in function_names for name in (
            "ZA_story_Template_battle_function",
            "ZA_story_Template_battle_function_active_level",
            "ZA_story_Template_battle_function_renda_route",
        ))
        observe_white_comment = (
            current_state in self.ZA_STORY_WHITE_COMMENT_RECOVERY_TARGETS)
        mega_before_comment_targets = getattr(
            self, "ZA_STORY_MEGA_BEFORE_COMMENT_RECOVERY_TARGETS", {})
        observe_mega_before_comment = (
            current_state in mega_before_comment_targets)
        white_comment_matched = [None]
        green_comment_matched = [None]
        battle_active_matched = [False]
        observe_image_checks = (
            observe_white_comment
            or observe_mega_before_comment
            or is_battle_function)
        if observe_image_checks:
            original_image_check = self.image_check
            had_instance_image_check = "image_check" in self.__dict__
            instance_image_check = self.__dict__.get("image_check")

            def observed_image_check(targetimage, *args, **kwargs):
                matched = original_image_check(targetimage, *args, **kwargs)
                if (str(targetimage) == "POKEMON_ZA_TEXT_WHITE_COMMENT"
                        and white_comment_matched[0] is None):
                    # 追加照合はせず、このStepが元々行う最初の判定だけを使う。
                    white_comment_matched[0] = bool(matched)
                if (observe_mega_before_comment
                        and str(targetimage)
                        == "POKEMON_ZA_TEXT_GREEN_COMMENT"
                        and green_comment_matched[0] is None):
                    # Mega前は白／緑のどちらかが成立すれば正常な会話開始。
                    green_comment_matched[0] = bool(matched)
                if (str(targetimage) in {
                        "POKEMON_ZA_BATTLE_BALL_CHECK",
                        "POKEMON_ZA_ESCAPE",
                        "POKEMON_ZA_BATTLE_ACTIVE_LEVEL"} and matched):
                    # 一度でも実バトルを検知した系列は、後からCOMMENTで
                    # beforeへ戻っても未突入復帰の対象にしない。
                    battle_active_matched[0] = True
                return matched

            self.image_check = observed_image_check
        try:
            next_state = state_function()
        finally:
            if observe_image_checks:
                if had_instance_image_check:
                    self.image_check = instance_image_check
                else:
                    del self.image_check

        # 対象FIELD Stepが通常遷移できず、正面視界が暗い時だけ復帰を開始。
        # 正常に次Stepへ進んだ場合やFURADARI区間外には影響させない。
        furadari_section_recovery = getattr(
            self, "ZA_story_furadari_section_recovery_step", None)
        if callable(furadari_section_recovery):
            next_state = furadari_section_recovery(
                current_state, next_state)
        if next_state != current_state:
            # EVENT mode 1の接近停滞回数は同じStepに留まる間だけ保持する。
            # 一度別Stepへ進んだ後に同じStepへ戻っても持ち越さない。
            self._za_markerdir_event_approach_step = None
            self._za_markerdir_event_approach_count = 0
            self._za_markerdir_event_approach_side_index = 0
        if is_lank_battle_zone and next_state != current_state:
            self._za_story_active_lank_battle_zone = None
        timers = getattr(
            self, "_za_story_event_entry_recovery_started", None)
        if timers is None:
            timers = {}
            self._za_story_event_entry_recovery_started = timers
        battle_before_exempt = getattr(
            self, "_za_story_battle_before_recovery_exempt", None)
        if battle_before_exempt is None:
            battle_before_exempt = set()
            self._za_story_battle_before_recovery_exempt = (
                battle_before_exempt)
        battle_return_counts = getattr(
            self, "_za_story_battle_return_counts", None)
        if battle_return_counts is None:
            battle_return_counts = {}
            self._za_story_battle_return_counts = battle_return_counts
        battle_active_states = getattr(
            self, "_za_story_battle_active_states", None)
        if battle_active_states is None:
            battle_active_states = set()
            self._za_story_battle_active_states = battle_active_states

        if is_battle_function and battle_active_matched[0]:
            battle_active_states.add(current_state)
            # 実バトルを一度でも確認した時点で、それ以前の未検知回数は破棄する。
            for before_state, (_, battle_state) in (
                    self.ZA_STORY_BATTLE_BEFORE_RECOVERY_TARGETS.items()):
                if battle_state == current_state:
                    battle_return_counts.pop(before_state, None)

        # battle_functionが実際にbattle_beforeへ戻した場合だけ、その待機中は
        # 町イベント未突入の復帰対象にしない。
        if (is_battle_function
                and next_state
                in self.ZA_STORY_BATTLE_BEFORE_RECOVERY_TARGETS):
            battle_before_exempt.add(next_state)
            timers.pop(next_state, None)
            if current_state in battle_active_states:
                # 実バトル検知後は、COMMENTによるbefore戻りを何度繰り返しても
                # 無限バトル／レベリングを抜ける復帰判定には使用しない。
                battle_return_counts.pop(next_state, None)
                return next_state
            return_count = battle_return_counts.get(next_state, 0) + 1
            battle_return_counts[next_state] = return_count
            if (return_count
                    >= self.ZA_STORY_BATTLE_RETURN_RECOVERY_COUNT):
                recovery_target = (
                    self.ZA_STORY_BATTLE_BEFORE_RECOVERY_TARGETS[
                        next_state][0])
                battle_return_counts.pop(next_state, None)
                if recovery_target != next_state:
                    battle_before_exempt.discard(next_state)
                    if (next_state == "2_STORY_ABSOL_MOVE17"
                            and recovery_target
                            == "2_STORY_ABSOL_MOVE14"):
                        self._ZA_story_reset_absol_infi_reentry(
                            "battle_return")
                    print(
                        "[BATTLE_RETURN_RECOVERY] {} -> {} ({} times)".format(
                            next_state, recovery_target, return_count))
                    return recovery_target
        elif is_battle_function and next_state != current_state:
            # 正常に別Stepへ進んだ場合は、このバトル系列の履歴を持ち越さない。
            battle_return_counts.clear()
            battle_active_states.discard(current_state)

        if current_state in self.ZA_STORY_WHITE_COMMENT_RECOVERY_TARGETS:
            if white_comment_matched[0] is not False:
                timers.pop(current_state, None)
                return next_state
            recovery_target = (
                self.ZA_STORY_WHITE_COMMENT_RECOVERY_TARGETS[current_state])
            return self._ZA_story_event_entry_recovery_timeout(
                current_state, recovery_target, next_state,
                "white_comment", timers)

        if observe_mega_before_comment:
            # 両方を実際に確認して不一致だった周回だけを未突入として数える。
            # 白または緑のどちらかが一致した場合や、判定自体を行わなかった
            # 周回では計時を解除する。
            comment_missing = (
                white_comment_matched[0] is False
                and green_comment_matched[0] is False)
            if not comment_missing:
                timers.pop(current_state, None)
                return next_state
            return self._ZA_story_event_entry_recovery_timeout(
                current_state,
                mega_before_comment_targets[current_state],
                next_state,
                "mega_before_comment",
                timers)

        battle_before = (
            self.ZA_STORY_BATTLE_BEFORE_RECOVERY_TARGETS.get(current_state))
        if battle_before is not None:
            recovery_target, success_state = battle_before
            if next_state == success_state:
                timers.pop(current_state, None)
                returned_from_battle = current_state in battle_before_exempt
                battle_before_exempt.discard(current_state)
                if not returned_from_battle:
                    # 初回進入時だけ新しいバトル系列として履歴を初期化する。
                    battle_active_states.discard(success_state)
                    battle_return_counts.pop(current_state, None)
                return next_state
            if current_state == "4_STORY_SHIRO_5":
                # SHIRO_5は停滞時間では復旧しない。実際に白Commentを
                # 3回閉じたときに_4_story_shiro_5が返すSHIRO_1をそのまま使う。
                timers.pop(current_state, None)
                if next_state == "4_STORY_SHIRO_1":
                    battle_before_exempt.discard(current_state)
                    battle_return_counts.pop(current_state, None)
                return next_state
            if current_state in battle_before_exempt:
                timers.pop(current_state, None)
                return next_state
            return self._ZA_story_event_entry_recovery_timeout(
                current_state, recovery_target, next_state,
                "battle_before", timers)

        return next_state

    def _ZA_story_reset_absol_infi_reentry(self, recovery_kind):
        """ABSOLの白Comment滞留復旧後だけZA_INFIを開始状態へ戻す。"""
        previous_chicketmaxflag = getattr(self, "chicketmaxflag", 0)
        self.chicketmaxflag = 0
        self.za_infi_main_current_state = "ZA_INFI_MAIN_START"
        self.bench_current_state = "BENCH_START"
        self.battle_current_state = "BATTLE_START"
        print(
            "[ABSOL_INFI_REENTRY] kind={} chicketmaxflag {} -> 0; "
            "ZA_INFI/bench/battle states reset".format(
                recovery_kind, previous_chicketmaxflag))

    def _ZA_story_reset_shiro_infi_entry(self, recovery_kind):
        """SHIRO開始・白Comment滞留復旧時のZA_INFIを初期化する。"""
        previous_chicketmaxflag = getattr(self, "chicketmaxflag", 0)
        self.chicketmaxflag = 0
        self.za_infi_main_current_state = "ZA_INFI_MAIN_START"
        self.bench_current_state = "BENCH_START"
        self.battle_current_state = "BATTLE_START"
        self.quasar_current_state = "QUASAR_START"
        self._4_story_shiro_white_comment_count = 0
        self._4_story_shiro_white_comment_latched = False
        self._4_story_shiro_infi_initialized = True
        reset_battle_flow = getattr(
            self, "_ZA_story_battle_flow_reset", None)
        if callable(reset_battle_flow):
            reset_battle_flow(
                "4_STORY_SHIRO_6", "shiro_infi_{}".format(recovery_kind))
        print(
            "[SHIRO_INFI_ENTRY] kind={} chicketmaxflag {} -> 0; "
            "ZA_INFI/bench/battle/quasar states reset".format(
                recovery_kind, previous_chicketmaxflag))

    def _ZA_story_event_entry_recovery_timeout(
            self, current_state, recovery_target, normal_return,
            recovery_kind, timers):
        now = time.monotonic()
        started = timers.get(current_state)
        if started is None:
            timers[current_state] = now
            return normal_return
        recovery_seconds = getattr(
            self, "ZA_STORY_EVENT_ENTRY_RECOVERY_SECONDS_BY_STATE", {}
        ).get(current_state, self.ZA_STORY_EVENT_ENTRY_RECOVERY_SECONDS)
        if now - started < recovery_seconds:
            return normal_return

        # 同じStepで毎周ログを出さないよう、復帰判定後に計時を始め直す。
        timers[current_state] = now
        furadari_comment_targets = getattr(
            self, "ZA_STORY_FURADARI_COMMENT_SKIP_TARGETS", {})
        if (recovery_kind == "white_comment"
                and furadari_comment_targets.get(current_state)
                == recovery_target
                and recovery_target != current_state):
            skipped_states = getattr(
                self, "_za_story_furadari_comment_skipped", None)
            if skipped_states is None:
                skipped_states = set()
                self._za_story_furadari_comment_skipped = skipped_states
            skipped_states.add(current_state)
        if (recovery_kind == "battle_before"
                and current_state == "2_STORY_ABSOL_MOVE17"
                and recovery_target == "2_STORY_ABSOL_MOVE14"):
            self._ZA_story_reset_absol_infi_reentry(
                "battle_before_timeout")
        if (recovery_kind == "white_comment"
                and current_state == "4_STORY_SHIRO_17"
                and recovery_target == "4_STORY_SHIRO_16"):
            # SHIRO_16の移動はセーブ位置基準。現在位置のまま
            # Stepだけ戻すと方向がずれるため、ゲームを復元する。
            # 再度SHIRO_17へ入った時は30秒を最初から計る。
            timers.pop(current_state, None)
            print(
                "[SHIRO_17_WHITE_TIMEOUT] white comment missing -> "
                "game reset and return to 4_STORY_SHIRO_16")
            self.ZA_gamereset()
        if (recovery_kind == "white_comment"
                and current_state == "4_STORY_SHIRO_44"
                and recovery_target == "4_STORY_SHIRO_43"):
            # SHIRO_43で出撃・攻撃をやり直した後は、
            # SHIRO_44の待ち時間を最初から計り直す。
            timers.pop(current_state, None)
            print(
                "[SHIRO_44_WHITE_TIMEOUT] white comment missing -> "
                "return to 4_STORY_SHIRO_43")
        print(
            "[EVENT_ENTRY_RECOVERY] {}: {} -> {}".format(
                recovery_kind, current_state, recovery_target))
        return recovery_target

