    def ZA_markerdir(self,type,search_mode=0,nofiled=False):
        if type == "EVENT":
            marker = "POKEMON_ZA_EVENT_MARKER"
        elif type == "PIN":
            marker = "POKEMON_ZA_PIN_MARKER"
        elif type == "SIDE_MARKER":
            marker = "POKEMON_ZA_SIDE_MARKER"
        else:
            return False

        center = marker + "_CENTER"
        center_wide = marker + "_CENTER_WIDE"
        wide_upper = marker + "_CENTER_WIDE_UPPER"
        wide_upper_left = marker + "_CENTER_WIDE_UPPER_LEFT"
        wide_upper_right = marker + "_CENTER_WIDE_UPPER_RIGHT"
        wide_upper_left_near = marker + "_CENTER_WIDE_UPPER_LEFT_NEAR"
        wide_upper_right_near = marker + "_CENTER_WIDE_UPPER_RIGHT_NEAR"
        wide_downer = marker + "_CENTER_WIDE_DOWNER"
        wide_downer_left = marker + "_CENTER_WIDE_DOWNER_LEFT"
        wide_downer_right = marker + "_CENTER_WIDE_DOWNER_RIGHT"
        wide_downer_left_near = marker + "_CENTER_WIDE_DOWNER_LEFT_NEAR"
        wide_downer_right_near = marker + "_CENTER_WIDE_DOWNER_RIGHT_NEAR"
        left_side = marker + "_CENTER_LEFT_SIDE"
        right_side = marker + "_CENTER_RIGHT_SIDE"
        left = marker + "_LEFT_WIDE"
        right = marker + "_RIGHT_WIDE"
        last_movement_name = "_za_markerdir_last_movement_" + marker
        downer_repeat_name = "_za_markerdir_downer_repeat_" + marker
        downer_stage_name = "_za_markerdir_downer_stage_" + marker
        downer_side_name = "_za_markerdir_downer_side_" + marker
        downer_angle_name = "_za_markerdir_downer_angle_" + marker
        marker_seen_name = "_za_markerdir_marker_seen_" + marker
        # 呼出元が「この1セットで一度でも見えたか」を判定できるようにし、
        # 単なる中央化失敗と完全未検知を区別する。
        setattr(self, marker_seen_name, False)

        def record_centered_event_approach():
            if type != "EVENT" or search_mode not in (1, 2):
                return
            story_state_attributes = {
                "MAIN_1_Z_LANK": "_1_story_current_state",
                "MAIN_2_Y_V_LANK": "_2_story_current_state",
                "MAIN_3_F_LANK": "_3_story_current_state",
                "MAIN_4_E_LANK": "_4_story_current_state",
                "MAIN_5_D_LANK": "_5_story_current_state",
                "MAIN_6_C_LANK": "_6_story_current_state",
                "MAIN_7_B_LANK": "_7_story_current_state",
                "MAIN_8_STORY_LAST": "_8_story_current_state",
            }
            main_state = getattr(self, "main_current_state", None)
            state_attribute = story_state_attributes.get(main_state)
            current_step = (
                getattr(self, state_attribute, None)
                if state_attribute else None)
            if current_step is None:
                return

            step_key = (main_state, current_step)
            step_name = "_za_markerdir_event_approach_step"
            count_name = "_za_markerdir_event_approach_count"
            side_name = "_za_markerdir_event_approach_side_index"
            if getattr(self, step_name, None) != step_key:
                setattr(self, step_name, step_key)
                setattr(self, count_name, 0)
                setattr(self, side_name, 0)

            # このTrueを受けた呼出元がEVENT方向へ1回移動する前提で、
            # 直前までに同じStepで完了した接近回数を保持する。
            approach_count = int(getattr(self, count_name, 0))
            if approach_count >= 10:
                side_index = int(getattr(self, side_name, 0))
                move_right = side_index % 2 == 0
                self.press(
                    Direction(
                        Stick.LEFT, 0 if move_right else 180, 1.0),
                    duration=0.3, wait=0.0)
                self.wait(0.1)
                print(
                    "[MARKER_APPROACH_RECOVERY] step={} "
                    "EVENT approach_count=10 move={} stick=LEFT "
                    "duration=0.3".format(
                        current_step,
                        "right" if move_right else "left"))
                setattr(self, side_name, side_index + 1)
                approach_count = 0
            setattr(self, count_name, approach_count + 1)

        def is_detected_in(target, detail):
            if not detail or not detail.get("matched"):
                return False
            x, y = detail["position"]
            width, height = detail["template_size"]
            for variant in self.IMAGE_DETECTION_TARGETS.get(target, []):
                crop = variant.get("crop", [])
                if not crop or len(crop) != 4 or not any(int(value) for value in crop):
                    return True
                x1, y1, x2, y2 = [int(value) for value in crop]
                if x >= x1 and y >= y1 and x + width <= x2 and y + height <= y2:
                    return True
            return False

        def detect_marker_position(variant):
            # F5 Reloadだけで反映できるよう、LocalFunction側の追加引数に
            # 依存せず、このサンプル関数内で全画面照合とマップ除外を行う。
            camera = getattr(self, "camera", None)
            if camera is None:
                return None
            if hasattr(camera, "readFreshFrame"):
                frame = camera.readFreshFrame(timeout=0.75)
            else:
                frame = camera.readFrame() if hasattr(
                    camera, "readFrame") else None
            if frame is None:
                return None

            template_path = str(variant.get("template_path", ""))
            normalized_path = template_path.replace("\\", "/")
            if (not os.path.isabs(template_path)
                    and normalized_path.startswith("Template/")):
                template_path = self.get_filespec(
                    normalized_path[len("Template/"):], mode="t")
            template = cv2.imread(template_path, cv2.IMREAD_COLOR)
            if template is None:
                return None

            source_match = frame
            template_match = template
            if variant.get("use_gray", False):
                source_match = cv2.cvtColor(
                    source_match, cv2.COLOR_BGR2GRAY)
                template_match = cv2.cvtColor(
                    template_match, cv2.COLOR_BGR2GRAY)
            if (source_match.shape[0] < template_match.shape[0]
                    or source_match.shape[1] < template_match.shape[1]):
                return None

            result = cv2.matchTemplate(
                source_match, template_match, cv2.TM_CCOEFF_NORMED)
            result = result.copy()
            result_height, result_width = result.shape[:2]
            template_height, template_width = template_match.shape[:2]
            # テンプレート矩形が左上マップへ少しでも重なる候補を除外する。
            exclusion_right = min(result_width, 210)
            exclusion_bottom = min(result_height, 210)
            if exclusion_right > 0 and exclusion_bottom > 0:
                result[0:exclusion_bottom, 0:exclusion_right] = -2.0
            _, score, _, location = cv2.minMaxLoc(result)
            threshold = float(variant.get("threshold", 0.8))
            matched = float(score) >= threshold
            show_value = bool(variant.get("show_value", False))
            if show_value:
                print("{} ZNCC value: {:.6f} / threshold: {:.6f}".format(
                    marker + "_POSITION", score, threshold))
            show_position = bool(variant.get("show_position", True))
            show_only_true_rect = bool(
                variant.get("show_only_true_rect", False))
            if (show_position and hasattr(self, "displayRectangle")
                    and (matched or not show_only_true_rect)):
                color = [
                    str(variant.get("match_color", "blue")), "orange"
                ] if matched else [
                    str(variant.get("no_match_color", "red")), "orange"
                ]
                self.displayRectangle(
                    location,
                    int(template_width),
                    int(template_height),
                    str(time.perf_counter()),
                    int(variant.get("ms", 2000)),
                    color=color,
                    crop=[])
            detail = {
                "name": marker + "_POSITION",
                "matched": matched,
                "score": float(score),
                "threshold": threshold,
                "position": location,
                "template_size": (
                    int(template_width), int(template_height)),
                "excluded_regions": [(0, 0, 210, 210)],
                "show_value": show_value,
                "timestamp": time.time(),
            }
            event_callback = getattr(self, "image_detection_event", None)
            if callable(event_callback):
                try:
                    event_callback(detail)
                except Exception:
                    pass
            return detail
    
        field_visible = self.image_check(
            "POKEMON_ZA_NO_BATTLE_FIELD_HARD_CHECK")
        if field_visible or nofiled: #FIELDから変更
            # search_mode=2はOUT_HOTEL_Z_23専用。FIELD上のNPC白吹き出しを
            # Switch_No3から取得した画像で検知し、現在の列から横へ外れ
            # その後EVENTの方向合わせを続行する。同じ検知中に横移動を
            # 重ねず、一度白Commentが消えた後の再検知で反対側を試す。
            if type == "EVENT" and search_mode == 2 and field_visible:
                escape_active_name = (
                    "_za_markerdir_field_white_escape_active_" + marker)
                escape_side_name = (
                    "_za_markerdir_field_white_escape_side_" + marker)
                field_white_visible = self.image_check(
                    "POKEMON_ZA_OUT_HOTEL_Z23_FIELD_WHITE_COMMENT")
                escape_active = bool(getattr(
                    self, escape_active_name, False))
                if field_white_visible and not escape_active:
                    side_index = int(getattr(self, escape_side_name, 0))
                    move_right = side_index % 2 == 0
                    self.press(
                        Direction(
                            Stick.LEFT, 0 if move_right else 180, 1.0),
                        duration=0.5, wait=0.0)
                    self.wait(0.1)
                    setattr(self, escape_active_name, True)
                    setattr(self, escape_side_name, side_index + 1)
                    print(
                        "[MARKER_FIELD_WHITE_ESCAPE] EVENT move={} "
                        "duration=0.5; realign marker".format(
                            "right" if move_right else "left"))
                elif not field_white_visible:
                    setattr(self, escape_active_name, False)

            # EVENTは1回の呼び出し内で最新フレームを取り直し、中央になるまで
            # 最大10回だけ方向補正する。PIN／SIDE_MARKERは従来どおり1回。
            alignment_attempts = 10 if type == "EVENT" else 1
            delayed_event_search = (
                type == "EVENT" and search_mode in (1, 2))
            undetected_search_attempts = 30 if delayed_event_search else 1
            marker_seen_this_call = False
            for alignment_index in range(alignment_attempts):
                movement_stick = Stick.RIGHT
                variants = self.IMAGE_DETECTION_TARGETS.get(center, [])
                detail = None
                if variants:
                    detail = detect_marker_position(variants[0])
                    self.last_image_detection = detail

                # search_mode=1は、1回の不一致ですぐ視点を動かさない。
                # EVENTが見えない間だけfresh frameを最大30回確認し、途中で
                # 見つかれば直ちに既存の中央化処理へ引き継ぐ。
                for search_index in range(1, undetected_search_attempts):
                    if detail and detail.get("matched"):
                        break
                    self.wait(0.1)
                    detail = None
                    if variants:
                        detail = detect_marker_position(variants[0])
                        self.last_image_detection = detail

                if detail and detail.get("matched"):
                    marker_seen_this_call = True
                    setattr(self, marker_seen_name, True)

                downer_detected = is_detected_in(wide_downer, detail)
                if not downer_detected:
                    setattr(self, downer_repeat_name, 0)
                    if detail and detail.get("matched"):
                        # 中央下以外へ位置が変わった場合は復帰段階を解除。
                        setattr(self, downer_stage_name, 0)
                        setattr(self, downer_angle_name, None)

                if is_detected_in(center, detail):
                    setattr(self, last_movement_name, None)
                    setattr(self, downer_repeat_name, 0)
                    setattr(self, downer_stage_name, 0)
                    setattr(self, downer_angle_name, None)
                    record_centered_event_approach()
                    return True
                elif downer_detected:
                    downer_repeat = int(getattr(
                        self, downer_repeat_name, 0)) + 1
                    setattr(self, downer_repeat_name, downer_repeat)
                    if downer_repeat >= 3:
                        recovery_stage = int(getattr(
                            self, downer_stage_name, 0))
                        if recovery_stage == 0:
                            side_index = int(getattr(
                                self, downer_side_name, 0))
                            recovery_angle = 0 if side_index % 2 == 0 else 180
                            recovery_stick = Stick.RIGHT
                            recovery_action = "VIEW_ROTATE"
                            setattr(self, downer_stage_name, 1)
                            setattr(self, downer_side_name, side_index + 1)
                            setattr(
                                self, downer_angle_name, recovery_angle)
                        else:
                            # 最初の視点回転後も再び中央下で停滞する場合だけ、
                            # 前回と同じ方向へ大きめに視点を回す。
                            recovery_angle = int(getattr(
                                self, downer_angle_name, 0) or 0)
                            recovery_stick = Stick.RIGHT
                            recovery_action = "VIEW_ROTATE"
                            setattr(self, downer_stage_name, 0)
                            setattr(self, downer_angle_name, None)
                        setattr(self, downer_repeat_name, 0)
                        setattr(self, last_movement_name, None)
                        self.press(
                            Direction(
                                recovery_stick, recovery_angle, 1.0),
                            duration=0.5, wait=0.0)
                        self.wait(0.1)
                        print(
                            "[MARKER_DOWNER_RECOVERY] marker={} "
                            "action={} angle={} duration=0.5".format(
                                marker, recovery_action, recovery_angle))
                        return False
                    movement = (270, 1.0, 0.0)
                elif is_detected_in(wide_upper, detail):
                    movement = (90, 1.0, 0.0)
                elif is_detected_in(wide_downer_left_near, detail):
                    movement = (180, 0.2, 0.0)
                elif is_detected_in(wide_downer_right_near, detail):
                    movement = (0, 0.2, 0.0)
                elif is_detected_in(wide_upper_left_near, detail):
                    movement = (180, 0.2, 0.0)
                elif is_detected_in(wide_upper_right_near, detail):
                    movement = (0, 0.2, 0.0)
                elif is_detected_in(wide_downer_left, detail):
                    movement = (180, 1.0, 0.03)
                elif is_detected_in(wide_downer_right, detail):
                    movement = (0, 1.0, 0.03)
                elif is_detected_in(wide_upper_left, detail):
                    movement = (180, 1.0, 0.03)
                elif is_detected_in(wide_upper_right, detail):
                    movement = (0, 1.0, 0.03)
                elif is_detected_in(left_side, detail):
                    movement = (180, 1.0, 0.03)
                elif is_detected_in(right_side, detail):
                    movement = (0, 1.0, 0.03)
                elif is_detected_in(left, detail):
                    if is_detected_in(center_wide, detail):
                        movement = (180, 0.2, 0.0)
                    else:
                        movement = (180, 1.0, 0.03)
                elif is_detected_in(right, detail):
                    if is_detected_in(center_wide, detail):
                        movement = (0, 0.2, 0.0)
                    else:
                        movement = (0, 1.0, 0.03)
                else:
                    if (type == "EVENT"
                            and (delayed_event_search
                                 or not marker_seen_this_call)):
                        # 通常は従来どおり右スティックの視点移動を切り替える。
                        # search_mode=1だけは30回連続不一致後、左スティックで
                        # キャラクターを右／左へ1回移動する。
                        scan_right = alignment_index % 2 == 0
                        scan_duration = 0.3 if delayed_event_search else (
                            0.03 if alignment_index == 0 else 0.06)
                        if delayed_event_search:
                            movement_stick = Stick.LEFT
                        movement = (
                            0 if scan_right else 180,
                            1.0,
                            scan_duration)
                        print(
                            "[MARKER_SEARCH] EVENT not found: scan {} "
                            "checks={} stick={} movement={}/{}".format(
                                "right" if scan_right else "left",
                                undetected_search_attempts,
                                "LEFT" if delayed_event_search else "RIGHT",
                                alignment_index + 1,
                                alignment_attempts))
                    else:
                        movement = getattr(self, last_movement_name, None)
                        if movement is None:
                            movement = (180, 1.0, 0.0)
                angle, magnitude, duration = movement
                self.press(Direction(movement_stick,angle,magnitude), duration=duration, wait=0.0)
                setattr(self, last_movement_name, movement)
                self.wait(0.1)
        return False

